package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                           // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)     // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                                 // PIC 99 len=2 = 0
var WsCount int64 = 0                                // PIC 99 len=2 = 0
var WsBalEd string                                   // PIC ZZ,ZZZ,ZZ9.99 len=13
var ScRec SchedRec

// file handling helpers (not part of COBOL working-storage)
var lines []string
var lineIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseDigits(s string) int64 {
	var n int64 = 0
	found := false
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
			found = true
		}
	}
	if !found {
		return 0
	}
	return n
}

func truncateWsBal(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0)
	scaledInt := scaled.IntPart()
	const modScaled int64 = 10000000000 // 10^10
	if scaledInt >= modScaled || scaledInt <= -modScaled {
		scaledInt = scaledInt % modScaled
	}
	return decimal.New(scaledInt, -2)
}

func formatPic99(val int64) string {
	// keep low-order 2 digits, COBOL high-order truncation
	v := val % 100
	if v < 0 {
		v = -v
	}
	// Go % keeps sign, but we want positive low digits
	// for val = 100 -> 0 ; for -1 handled as above
	// ensure for negative original we still produce positive
	// Normalize: val %100 may be negative, we took abs. For overflow beyond 100 need positive remainder
	// Example val=101 => 1 => "01" correct
	// Use absolute value modulo properly
	if val < 0 {
		// recompute positive modulo
		av := -val
		v = av % 100
	}
	return fmt.Sprintf("%02d", v)
}

func formatWsBalEd(v decimal.Decimal) string {
	scaled := v.Shift(2).Truncate(0).IntPart()
	signNeg := scaled < 0
	if signNeg {
		scaled = -scaled
	}
	integerPart := scaled / 100
	fracPart := scaled % 100
	const pow8 int64 = 100000000 // 10^8
	if integerPart >= pow8 {
		integerPart = integerPart % pow8
	}
	integerStr := fmt.Sprintf("%08d", integerPart)
	fracStr := fmt.Sprintf("%02d", fracPart)

	tmplInt := "ZZ,ZZZ,ZZ9" // 10 chars
	resInt := make([]byte, len(tmplInt))
	digitIdx := 0
	suppress := true
	for i, ch := range tmplInt {
		if ch == 'Z' || ch == '9' {
			d := integerStr[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if suppress && d == '0' {
					resInt[i] = ' '
				} else if d != '0' {
					resInt[i] = d
					suppress = false
				} else {
					// d == '0' and not suppress
					resInt[i] = '0'
				}
			} else { // '9'
				resInt[i] = d
				if d != '0' {
					suppress = false
				}
			}
		} else if ch == ',' {
			if suppress {
				resInt[i] = ' '
			} else {
				resInt[i] = ','
			}
		}
	}
	// sign handling: picture has no sign, COBOL would show without sign;
	// we ignore sign for this task (assume positive)
	_ = signNeg
	return string(resInt) + "." + fracStr
}

// READ-PARA.
func ReadPara() {
	if lineIdx >= len(lines) {
		WsEofFlag = "Y"
		return
	}
	line := lines[lineIdx]
	lineIdx++
	if len(line) < 16 {
		line += strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	ScRec.ScAcct = line[0:4]
	prinField := line[4:11]
	prinDigits := parseDigits(prinField)
	ScRec.ScPrin = decimal.New(prinDigits, -2)
	rateField := line[11:15]
	rateDigits := parseDigits(rateField)
	ScRec.ScRate = decimal.New(rateDigits, -2)
	yearsField := line[15:16]
	ScRec.ScYears = parseDigits(yearsField)
}

// PROCESS-PARA.
func ProcessPara() {
	WsBal = ScRec.ScPrin
	WsBal = truncateWsBal(WsBal)
	for WsYear = 1; WsYear <= ScRec.ScYears; WsYear++ {
		factor := decimal.NewFromInt(1).Add(ScRec.ScRate.Shift(-2))
		newBal := WsBal.Mul(factor)
		rounded := newBal.Round(2)
		WsBal = truncateWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		yearStr := formatPic99(WsYear)
		fmt.Printf("%s Y%s %s\n", ScRec.ScAcct, yearStr, WsBalEd)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", ScRec.ScAcct, WsBalEd)
	WsCount++
	if WsCount >= 100 || WsCount < 0 {
		// high-order truncation for PIC 99
		WsCount = WsCount % 100
		if WsCount < 0 {
			WsCount = -WsCount
		}
	}
	ReadPara()
}

// MAIN-PARA.
func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat failed: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	// read all lines preserving trailing spaces
	var ls []string
	r := bufio.NewReader(f)
	for {
		line, err := r.ReadString('\n')
		if err != nil && len(line) == 0 {
			if err == io.EOF {
				break
			}
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		if strings.HasSuffix(line, "\n") {
			line = line[:len(line)-1]
		}
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
		ls = append(ls, line)
		if err == io.EOF {
			break
		}
		if err != nil && err != io.EOF {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
	}
	lines = ls
	lineIdx = 0

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE SCHED-FILE is handled by defer
	cntStr := formatPic99(WsCount)
	fmt.Printf("SCHEDULES: %s\n", cntStr)
}

func main() {
	MainPara()
}
